/**
 * screenSC001 - 자동 생성된 CRUD API
 * 
 * @generated by AI Factory Lab
 */

import { z } from 'zod';
import { createTRPCRouter, publicProcedure } from '~/server/api/trpc';
import { db } from '~/server/db';

// 입력 스키마
const rowSchema = z.object({
  cust_cd: z.string().max(20),
  cust_nm: z.string().max(100),
  biz_no: z.string().max(13).optional(),
  repr_nm: z.string().max(50).optional(),
  biz_type: z.string().optional(),
  biz_cond: z.string().optional(),
  cust_type: z.string(),
  tel_no: z.string().optional(),
  fax_no: z.string().optional(),
  email: z.string().optional(),
  address: z.string().optional(),
  pic_nm: z.string().optional(),
  use_yn: z.boolean(),
  remark: z.string().optional(),
  created_at: z.string().optional(),
  updated_at: z.string().optional(),
});

const saveInputSchema = z.object({
  inserts: z.array(rowSchema),
  updates: z.array(rowSchema),
  deletes: z.array(z.string()),
});

export const screenSC001Router = createTRPCRouter({
  // 전체 조회
  getAll: publicProcedure.query(async () => {
    const result = await db.tbCustomer.findMany({
      
      orderBy: { cust_nm: 'asc' },
    });
    return result;
  }),

  // 단건 조회
  getById: publicProcedure
    .input(z.string())
    .query(async ({ input }) => {
      const result = await db.tbCustomer.findUnique({
        where: { cust_cd: input },
      });
      return result;
    }),

  // 일괄 저장 (Insert/Update/Delete)
  save: publicProcedure
    .input(saveInputSchema)
    .mutation(async ({ input }) => {
      const { inserts, updates, deletes } = input;
      
      // 트랜잭션으로 일괄 처리
      await db.$transaction(async (tx) => {
        // Insert
        if (inserts.length > 0) {
          await tx.tbCustomer.createMany({
            data: inserts.map(row => ({
              ...row,
              createdAt: new Date(),
              updatedAt: new Date(),
            })),
          });
        }

        // Update
        for (const row of updates) {
          await tx.tbCustomer.update({
            where: { cust_cd: row.cust_cd },
            data: {
              ...row,
              updatedAt: new Date(),
            },
          });
        }

        // Delete (soft delete or hard delete)
        if (deletes.length > 0) {
          await tx.tbCustomer.deleteMany({
            where: { cust_cd: { in: deletes } },
          });
        }
      });

      return { 
        success: true, 
        insertedCount: inserts.length,
        updatedCount: updates.length,
        deletedCount: deletes.length,
      };
    }),
});
